        "answers": {
          "a": true,
          "b": false,
          "c": true,
          "d": false
        },
        "explanation": "Ta có Lợi nhuận = Tổng doanh thu − Tổng chi phí.<br>Tổng doanh thu là R = PQ = 400Q − 2Q² và tổng chi phí là C = Q<span style=\"text-decoration:overline\">C</span> = 0,2Q² + 4Q + 400, nên lợi nhuận:<br>P(Q) = R − C = 396Q − 2,2Q² − 400.<br>P'(Q) = 0 ⇔ 396 − 4,4Q = 0 ⇔ Q = 90. Ta có P''(Q) = −4,4 < 0 nên lợi nhuận đạt cực đại tại Q = 90. Vậy (a) Đúng.<br>Thay Q = 90 vào hàm cầu: P = 400 − 2(90) = 220$. Vậy (b) Sai.<br>Lợi nhuận tối đa: P(90) = 396(90) − 2,2(90)² − 400 = 17420$. Vậy (c) Đúng.<br>Khi đánh thuế 22$/đơn vị, hàm lợi nhuận mới là P<sub>1</sub>(Q) = 374Q − 2,2Q² − 400.<br>P<sub>1</sub>'(Q) = 0 ⇔ 374 − 4,4Q = 0 ⇔ Q = 85 ⇒ giá bán P<sub>1</sub> = 400 − 2(85) = 230$. Vậy (d) Sai."
