        "question": "Để đánh giá độ chính xác của hai hệ thống đóng gói tự động các túi cà phê của hai phân xưởng người ta đã tiến hành thu thập mẫu số liệu về khối lượng của một số gói cà phê của mỗi phân xưởng cho kết quả như sau:<br>Phân xưởng A: 203, 207, 205, 197, 208, 192, 206, 202, 200, 196, 195, 194, 203, 197, 193, 199, 198, 195, 206, 204.<br>Phân xưởng B:<br><table class=\"data-table\"><tr><th>Cân nặng</th><td>[190; 194)</td><td>[194; 198)</td><td>[198; 202)</td><td>[202; 206)</td><td>[206; 210)</td></tr><tr><th>Số gói</th><td>2</td><td>5</td><td>6</td><td>5</td><td>2</td></tr></table><br>Tính số trung bình và độ lệch chuẩn của khối lượng một gói cà phê do các phân xưởng A, B sản xuất. Dựa trên kết quả tính được, hãy nêu nhận xét về độ chính xác của hai hệ thống đóng gói.",
        "explanation": "Cỡ mẫu tương ứng là n = 20, m = 20.<br>Số trung bình của mẫu số liệu về khối lượng các gói cà phê của phân xưởng A là:<br><span style=\"text-decoration:overline\">x</span><sub>A</sub> = <span class=\"m-frac\"><span class=\"num\">1</span><span class=\"den\">20</span></span>(203 + ... + 204) = 200.<br>Xét mẫu số liệu của phân xưởng B, chọn giá trị đại diện cho các nhóm lần lượt là 192, 196, 200, 204, 208 (số gói tương ứng: 2, 5, 6, 5, 2).<br>Số trung bình của phân xưởng B: <span style=\"text-decoration:overline\">x</span><sub>B</sub> = <span class=\"m-frac\"><span class=\"num\">1</span><span class=\"den\">20</span></span>(2·192 + 5·196 + 6·200 + 5·204 + 2·208) = 200.<br>Độ lệch chuẩn của phân xưởng A: s<sub>A</sub> = <span class=\"m-root\">√<span class=\"m-rad\"><span class=\"m-frac\"><span class=\"num\">1</span><span class=\"den\">20</span></span>(203² + ... + 204²) − 200²</span></span> ≈ 4,93.<br>Độ lệch chuẩn của phân xưởng B: s<sub>B</sub> ≈ 4,56.<br>Nhận xét: Vì s<sub>B</sub> < s<sub>A</sub> nên hệ thống đóng gói của phân xưởng B chính xác hơn của phân xưởng A."
