        "question": "Một con nhện đang treo mình dưới một sợi tơ theo phương thẳng đứng thì bị một cơn gió thổi theo phương ngang làm dây treo lệch đi so với phương thẳng đứng một góc 30°. Biết trọng lượng của con nhện là P = 0,1 N. Xác định độ lớn của lực mà gió tác dụng lên con nhện ở vị trí cân bằng. (kết quả làm tròn đến hàng phần trăm)",
        "explanation": "Các lực tác dụng lên con nhện là lực căng dây <span class=\"m-vec\">T</span>, trọng lực <span class=\"m-vec\">P</span> và lực gió <span class=\"m-vec\">F</span>.<br>Do con nhện ở vị trí cân bằng nên <span class=\"m-vec\">T</span> + <span class=\"m-vec\">F</span> + <span class=\"m-vec\">P</span> = <span class=\"m-vec\">0</span> ⇒ −<span class=\"m-vec\">T</span> = <span class=\"m-vec\">P</span> + <span class=\"m-vec\">F</span>.<br>Ta có tan 30° = <span class=\"m-frac\"><span class=\"num\">|<span class=\"m-vec\">F</span>|</span><span class=\"den\">|<span class=\"m-vec\">P</span>|</span></span> ⇒ |<span class=\"m-vec\">F</span>| = |<span class=\"m-vec\">P</span>| · tan 30° = 0,1 · <span class=\"m-frac\"><span class=\"num\"><span class=\"m-root\">√<span class=\"m-rad\">3</span></span></span><span class=\"den\">3</span></span> = <span class=\"m-frac\"><span class=\"num\"><span class=\"m-root\">√<span class=\"m-rad\">3</span></span></span><span class=\"den\">30</span></span> ≈ 0,058 N (làm tròn hàng phần trăm là 0,06 N; theo đáp án đề bài ghi <span class=\"m-frac\"><span class=\"num\"><span class=\"m-root\">√<span class=\"m-rad\">3</span></span></span><span class=\"den\">10</span></span> ≈ 0,058 N)."
