        "explanation": "<b>a) Đúng.</b> Gọi số lần tăng giá cho thuê mỗi căn hộ mỗi tháng để công ty có doanh thu cao nhất là x (lần) (0 ≤ x ≤ 30).<br>Số căn hộ bị bỏ trống mỗi tháng là 5x. Giá cho thuê mỗi căn hộ là 2 + 0,1x (triệu đồng).<br>Do có 10 căn hộ bị trống nên 5x = 10 ⇔ x = 2. Khi đó, giá cho thuê mỗi căn hộ là 2 + 0,1·2 = 2,2 (triệu đồng).<br><b>b) Sai.</b> Số căn hộ mỗi tháng được thuê là 150 − 5x (căn hộ). Doanh thu của công ty đạt được là f(x) = (2 + 0,1x)(150 − 5x) với 0 ≤ x ≤ 30.<br>f′(x) = 0,1(150 − 5x) − 5(2 + 0,1x) = 5 − x; f′(x) = 0 ⇔ x = 5.<br>f(0) = 300; f(5) = 312,5; f(30) = 0 ⇒ max<sub>[0;30]</sub> f(x) = f(5) = 312,5.<br>Vậy để có doanh thu cao nhất thì công ty đó phải cho thuê với giá 2 + 0,1·5 = 2,5 (triệu đồng).<br><b>c) Đúng.</b> Do max<sub>[0;30]</sub> f(x) = f(5) = 312,5 nên doanh thu cao nhất của công ty đạt được là 312,5 triệu đồng.<br><b>d) Đúng.</b> Khi doanh thu cao nhất (x = 5), số căn hộ có người thuê là 150 − 5·5 = 125 căn hộ."
