        "explanation": "Lấy điểm M(x; <span class=\"m-frac\"><span class=\"num\">−x² + 2</span><span class=\"den\">x</span></span>), x ≠ 0 thuộc đồ thị (C): y = <span class=\"m-frac\"><span class=\"num\">−x² + 2</span><span class=\"den\">x</span></span>.<br>Khi đó OM² = x² + (<span class=\"m-frac\"><span class=\"num\">−x² + 2</span><span class=\"den\">x</span></span>)² = 2x² + <span class=\"m-frac\"><span class=\"num\">4</span><span class=\"den\">x²</span></span> − 4 ≥ 4<span class=\"m-root\">√<span class=\"m-rad\">2</span></span> − 4.<br>Suy ra OM ≥ 2<span class=\"m-root\">√<span class=\"m-rad\"><span class=\"m-root\">√<span class=\"m-rad\">2</span></span> − 1</span></span>.<br>Dấu \"=\" xảy ra khi và chỉ khi 2x² = <span class=\"m-frac\"><span class=\"num\">4</span><span class=\"den\">x²</span></span> ⇔ x = ±<span class=\"m-root\">√<span class=\"m-rad\">2</span></span>.<br>Vậy độ dài tuyến cáp treo ngắn nhất bằng OM = 2<span class=\"m-root\">√<span class=\"m-rad\"><span class=\"m-root\">√<span class=\"m-rad\">2</span></span> − 1</span></span> ≈ 1,29."
