        "explanation": "Đổi 60 cm = 0,6 m. Ta có SA = 0,6 m.<br>A′(0; 0; 0), A(0; 0; 1), B(0; 0,5; 1) ⇒ AB = <span class=\"m-frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span>, AA′ = 1.<br>Gọi I = AC ∩ BD, I′ = A′C′ ∩ B′D′.<br>Vì S.ABCD là khối chóp tứ giác đều nên ABCD là hình vuông và SI ⊥ (ABCD).<br>Vì ABCD.A′B′C′D′ là hình hộp chữ nhật nên (ABCD) // (A′B′C′D′), II′ ⊥ (A′B′C′D′). Do đó S, I, I′ thẳng hàng và SI′ ⊥ (A′B′C′D′).<br>Xét tam giác vuông ABC có AC = <span class=\"m-root\">√<span class=\"m-rad\">AB² + BC²</span></span> = <span class=\"m-frac\"><span class=\"num\"><span class=\"m-root\">√<span class=\"m-rad\">2</span></span></span><span class=\"den\">2</span></span> ⇒ AI = <span class=\"m-frac\"><span class=\"num\"><span class=\"m-root\">√<span class=\"m-rad\">2</span></span></span><span class=\"den\">4</span></span>.<br>Xét tam giác vuông SIA có SI = <span class=\"m-root\">√<span class=\"m-rad\">SA² − AI²</span></span> = <span class=\"m-root\">√<span class=\"m-rad\">0,6² − (<span class=\"m-frac\"><span class=\"num\"><span class=\"m-root\">√<span class=\"m-rad\">2</span></span></span><span class=\"den\">4</span></span>)²</span></span> = <span class=\"m-frac\"><span class=\"num\"><span class=\"m-root\">√<span class=\"m-rad\">94</span></span></span><span class=\"den\">20</span></span>.<br>Suy ra SI′ = II′ + SI = 1 + <span class=\"m-frac\"><span class=\"num\"><span class=\"m-root\">√<span class=\"m-rad\">94</span></span></span><span class=\"den\">20</span></span> = <span class=\"m-frac\"><span class=\"num\">20 + <span class=\"m-root\">√<span class=\"m-rad\">94</span></span></span><span class=\"den\">20</span></span>.<br>Ta có I′(0,25; 0,25; 0) là hình chiếu của S trên mặt phẳng Oxy nên S(0,25; 0,25; <span class=\"m-frac\"><span class=\"num\">20 + <span class=\"m-root\">√<span class=\"m-rad\">94</span></span></span><span class=\"den\">20</span></span>).<br>⇒ a + b + c = 0,25 + 0,25 + <span class=\"m-frac\"><span class=\"num\">20 + <span class=\"m-root\">√<span class=\"m-rad\">94</span></span></span><span class=\"den\">20</span></span> ≈ 1,98."
