        "question": "Trong không gian với hệ tọa độ Oxyz cho tứ diện ABCD với A(0; 0; 1), B(0; 1; 0), C(1; 0; 0) và D(−2; 3; −1). Thể tích khối tứ diện ABCD bằng",
