        "figure": null,
        "question": "Một công ty bất động sản có 150 căn hộ cho thuê, biết rằng nếu cho thuê mỗi căn hộ với giá 2 triệu đồng mỗi tháng thì mỗi căn hộ đều có người thuê và cứ mỗi lần tăng giá cho thuê mỗi căn hộ thêm 100.000 đồng mỗi tháng thì có thêm 5 căn hộ bị bỏ trống. Các mệnh đề sau đúng hay sai?",
        "statements": {
          "a": "Khi giá cho thuê mỗi căn hộ là 2.200.000 đồng thì có 10 căn hộ bị trống.",
          "b": "Khi giá cho thuê mỗi căn hộ là 2.700.000 đồng thì thu nhập của công ty cao nhất.",
          "c": "Thu nhập cao nhất của công ty đạt được là 312.500.000 đồng.",
          "d": "Khi thu nhập công ty cao nhất thì số căn hộ có người thuê là 125 căn hộ."
        },
        "answers": {
          "a": true,
          "b": false,
          "c": true,
          "d": true
        },
        "explanation": "Gọi số lần tăng giá tiền thuê mỗi căn hộ một tháng để công ty thu nhập cao nhất là x (0 ≤ x ≤ 30).<br>Số tiền cho thuê mỗi căn hộ là 2 + 0,1x (triệu đồng).<br>Số căn hộ mỗi tháng được thuê là 150 − 5x.<br>Thu nhập của công ty là f(x) = (2 + 0,1x)(150 − 5x) (triệu đồng).<br>⇒ f′(x) = 5 − x = 0 ⇔ x = 5 (nhận).<br>f(0) = 300; f(5) = 312,5; f(30) = 0 ⇒ max<sub>[0; 30]</sub> f(x) = 312,5.<br><b>a) Đúng.</b> Với giá 2.200.000 đồng (x = 2) thì số căn hộ bị trống là 5 · 2 = 10 căn hộ.<br><b>b) Sai.</b> Thu nhập của công ty cao nhất khi giá cho thuê là 2 + 0,1 · 5 = 2,5 triệu đồng (2.500.000 đồng).<br><b>c) Đúng.</b> Thu nhập cao nhất là 312.500.000 đồng khi x = 5.<br><b>d) Đúng.</b> Số căn hộ mỗi tháng được thuê là 150 − 5 · 5 = 125 căn hộ."
