        "question": "Một chất điểm A nằm trên mặt phẳng nằm ngang (α), chịu tác động bởi ba lực <span class=\"m-vec\">F</span><sub>1</sub>, <span class=\"m-vec\">F</span><sub>2</sub>, <span class=\"m-vec\">F</span><sub>3</sub>. Các lực <span class=\"m-vec\">F</span><sub>1</sub>, <span class=\"m-vec\">F</span><sub>2</sub> có giá nằm trong (α) và (<span class=\"m-vec\">F</span><sub>1</sub>, <span class=\"m-vec\">F</span><sub>2</sub>) = 135°, còn lực <span class=\"m-vec\">F</span><sub>3</sub> có giá vuông góc với (α) và hướng lên trên. Xác định tổng hợp lực của các lực trên, biết rằng độ lớn của ba lực đó lần lượt là 20 N, 15 N và 10 N. (Kết quả làm tròn đến hàng phần chục).",
        "explanation": "Ta có <span class=\"m-vec\">F</span> = <span class=\"m-vec\">F</span><sub>1</sub> + <span class=\"m-vec\">F</span><sub>2</sub> + <span class=\"m-vec\">F</span><sub>3</sub>.<br>Suy ra <span class=\"m-vec\">F</span>² = (<span class=\"m-vec\">F</span><sub>1</sub> + <span class=\"m-vec\">F</span><sub>2</sub> + <span class=\"m-vec\">F</span><sub>3</sub>)²<br>= F<sub>1</sub>² + F<sub>2</sub>² + F<sub>3</sub>² + 2<span class=\"m-vec\">F</span><sub>1</sub> · <span class=\"m-vec\">F</span><sub>2</sub> + 2<span class=\"m-vec\">F</span><sub>2</sub> · <span class=\"m-vec\">F</span><sub>3</sub> + 2<span class=\"m-vec\">F</span><sub>1</sub> · <span class=\"m-vec\">F</span><sub>3</sub><br>= 20² + 15² + 10² + 2 · 20 · 15 · cos 135° = 725 − 300<span class=\"m-root\">√<span class=\"m-rad\">2</span></span>.<br>Suy ra |<span class=\"m-vec\">F</span>| = <span class=\"m-root\">√<span class=\"m-rad\">725 − 300<span class=\"m-root\">√<span class=\"m-rad\">2</span></span></span></span> ≈ 17,3.<br>Vậy độ lớn của tổng hợp lực là 17,3 N."
