        "explanation": "Gọi <span class=\"m-vec\">F<sub>1</sub></span>, <span class=\"m-vec\">F<sub>2</sub></span>, <span class=\"m-vec\">F<sub>3</sub></span> là ba lực tác động vào vật đặt tại điểm O lần lượt có độ lớn là 25 N, 12 N và 4 N.<br>Vẽ <span class=\"m-vec\">OA</span> = <span class=\"m-vec\">F<sub>1</sub></span>, <span class=\"m-vec\">OB</span> = <span class=\"m-vec\">F<sub>2</sub></span>, <span class=\"m-vec\">OC</span> = <span class=\"m-vec\">F<sub>3</sub></span>. Dựng hình bình hành OADB và hình bình hành ODEC.<br>Hợp lực tác động vào vật là <span class=\"m-vec\">F</span> = <span class=\"m-vec\">OA</span> + <span class=\"m-vec\">OB</span> + <span class=\"m-vec\">OC</span> = <span class=\"m-vec\">OD</span> + <span class=\"m-vec\">OC</span> = <span class=\"m-vec\">OE</span>.<br>Áp dụng định lý cô-sin trong tam giác OBD, ta có OD² = OA² + OB² + 2 · OA · OB · cos 120°.<br>Vì OC ⊥ (OADB) nên OC ⊥ OD, suy ra ODEC là hình chữ nhật, do đó tam giác ODE vuông tại D.<br>OE² = OC² + OD² = OC² + OA² + OB² + 2 · OA · OB · cos 120°.<br>Suy ra OE = <span class=\"m-root\">√<span class=\"m-rad\">4² + 25² + 12² + 2 · 25 · 12 · cos 120°</span></span> ≈ 22.<br>Vậy độ lớn của hợp lực là F = OE ≈ 22 N."
