        "question": "Cho tứ diện đều ABCD có cạnh bằng a và M là trung điểm của CD.<br>Tính các tích vô hướng <span class=\"m-vec\">AB</span> · <span class=\"m-vec\">AC</span>, <span class=\"m-vec\">AB</span> · <span class=\"m-vec\">AM</span>.<br>Tính góc (<span class=\"m-vec\">AB</span>, <span class=\"m-vec\">CD</span>).",
