        "question": "Một hòn đảo nhỏ cách điểm P trên bờ biển khoảng 3 km, một thị trấn ở điểm A cách điểm P 12 km. Nếu một người trên đảo chèo thuyền với vận tốc 2,5 km/h và đi bộ với vận tốc 4 km/h thì thuyền nên neo đậu ở vị trí nào trên đoạn PA để người đó đến thị trấn trong thời gian ngắn nhất?",
        "explanation": "Gọi khoảng cách từ thị trấn A đến chỗ neo thuyền là x (km), với 0 ≤ x ≤ 12.<br>Từ đề bài, khoảng cách từ hòn đảo đến nơi neo thuyền là <span class=\"m-root\">√<span class=\"m-rad\">(12 − x)² + 9</span></span> (km).<br>Thời gian để người đó từ hòn đảo đến thị trấn là T(x) = <span class=\"m-frac\"><span class=\"num\"><span class=\"m-root\">√<span class=\"m-rad\">(12 − x)² + 9</span></span></span><span class=\"den\">2,5</span></span> + <span class=\"m-frac\"><span class=\"num\">x</span><span class=\"den\">4</span></span>.<br>Ta có T′(x) = −<span class=\"m-frac\"><span class=\"num\">12 − x</span><span class=\"den\">2,5<span class=\"m-root\">√<span class=\"m-rad\">(12 − x)² + 9</span></span></span></span> + <span class=\"m-frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> = 0 ⇔ x = 11,6875 (lưu ý giải phương trình cho x = 12 − <span class=\"m-frac\"><span class=\"num\">3 · 2,5</span><span class=\"den\"><span class=\"m-root\">√<span class=\"m-rad\">4² − 2,5²</span></span></span></span> ≈ 9,59 km nếu tính chính xác; theo đáp án in trong đề là 11,6875 km).<br>Mặt khác, T(0) ≈ 4,94; T(12) = 4,2; T(11,6875) ≈ 4,13.<br>Vậy người đó cần neo thuyền tại vị trí cách thị trấn A khoảng 11,6875 km (tức cách P khoảng 0,3125 km) theo đáp án của đề."
