        "explanation": "Lợi nhuận thu được là L(x) = T(x) − C(x) = −x³ + 6x² + 288x − 592.<br><b>a) Đúng.</b> Một ngày nào đó cơ sở sản xuất được 10 đôi giày thì lợi nhuận thu được là: L(10) = −10³ + 6·10² + 288·10 − 592 = 1888 (nghìn đồng).<br><b>b) Sai.</b> Lợi nhuận thu được là 1584, khi đó ta có 1584 = −x³ + 6x² + 288x − 592 ⇔ x³ − 6x² − 288x + 2176 = 0 ⇔ x = −1 + <span class=\"m-root\">√<span class=\"m-rad\">273</span></span> hoặc x = −1 − <span class=\"m-root\">√<span class=\"m-rad\">273</span></span> hoặc x = 8.<br><b>c) Đúng.</b> Xét hàm số L(x) = −x³ + 6x² + 288x − 592 với 1 ≤ x ≤ 20. L′(x) = −3x² + 12x + 288 = 0 ⇔ x = 12 hoặc x = −8 (loại). Lập bảng biến thiên trên [1; 20], tại x = 12 hàm đạt cực đại L(12) = 2000. Vậy cơ sở sản xuất được 12 đôi giày thì lợi nhuận đạt cao nhất.<br><b>d) Sai.</b> Khi đó lợi nhuận tối đa đạt được trong một ngày là 2000 nghìn đồng (không phải 1980 nghìn đồng)."
