        "answer": "1,92",
        "explanation": "Gọi (d₁): y = −x + m (với m > 4) song song với (d): y = −x + 4 và cắt (C): y = <span class=\"m-frac\"><span class=\"num\">2x + 1</span><span class=\"den\">x − 1</span></span> tại hai điểm phân biệt B, C (x<sub>B</sub>, x<sub>C</sub> > 1).<br>Phương trình hoành độ giao điểm của (d₁) và (C): <span class=\"m-frac\"><span class=\"num\">2x + 1</span><span class=\"den\">x − 1</span></span> = −x + m ⇔ x² + (1 − m)x + m + 1 = 0.<br>Δ = m² − 6m − 3 > 0 ⇔ m > 3 + 2<span class=\"m-root\">√<span class=\"m-rad\">3</span></span> hoặc m < 3 − 2<span class=\"m-root\">√<span class=\"m-rad\">3</span></span> ⇔ m > 3 + 2<span class=\"m-root\">√<span class=\"m-rad\">3</span></span> (vì m > 4) (1).<br>Khi đó ta có: x<sub>C</sub> + x<sub>B</sub> = m − 1 và x<sub>C</sub>·x<sub>B</sub> = m + 1.<br>Suy ra CB² = 2(x<sub>B</sub> − x<sub>C</sub>)² = 2(x<sub>B</sub> + x<sub>C</sub>)² − 8x<sub>B</sub>·x<sub>C</sub> = 2m² − 12m − 6.<br>Mặt khác chọn I(0; 4) ∈ (d), ta có khoảng cách giữa hai đường thẳng (d); (d₁) bằng AB = d(I; (d₁)) = <span class=\"m-frac\"><span class=\"num\">|4 − m|</span><span class=\"den\"><span class=\"m-root\">√<span class=\"m-rad\">2</span></span></span></span> = <span class=\"m-frac\"><span class=\"num\">m − 4</span><span class=\"den\"><span class=\"m-root\">√<span class=\"m-rad\">2</span></span></span></span>.<br>Để ABCD là hình vuông thì AB² = BC² ⇔ <span class=\"m-frac\"><span class=\"num\">(m − 4)²</span><span class=\"den\">2</span></span> = 2m² − 12m − 6 ⇔ m = <span class=\"m-frac\"><span class=\"num\">8 ± 2<span class=\"m-root\">√<span class=\"m-rad\">37</span></span></span><span class=\"den\">3</span></span>.<br>Kết hợp điều kiện (1) suy ra m = <span class=\"m-frac\"><span class=\"num\">8 + 2<span class=\"m-root\">√<span class=\"m-rad\">37</span></span></span><span class=\"den\">3</span></span>.<br>Vậy khoảng cách giữa hai cột đèn bên bờ hồ bằng <span class=\"m-frac\"><span class=\"num\"><span class=\"m-frac\"><span class=\"num\">8 + 2<span class=\"m-root\">√<span class=\"m-rad\">37</span></span></span><span class=\"den\">3</span></span> − 4</span><span class=\"den\"><span class=\"m-root\">√<span class=\"m-rad\">2</span></span></span></span> ≈ 1,92.",
