        "explanation": "Gọi tọa độ ban đầu của máy bay tại thời điểm t = 0 là A(200; 70; 118).<br>Sau 50 giây, độ cao giảm 400 m nên tọa độ z giảm 4 đơn vị, tức là z = 114. Gọi tọa độ sau 50 giây là B(x; y; 114).<br>Vận tốc bay (giả sử bay thẳng đều): <span class=\"m-vec\">v</span> = <span class=\"m-frac\"><span class=\"num\"><span class=\"m-vec\">AB</span></span><span class=\"den\">50</span></span> = (<span class=\"m-frac\"><span class=\"num\">x − 200</span><span class=\"den\">50</span></span>; <span class=\"m-frac\"><span class=\"num\">y − 70</span><span class=\"den\">50</span></span>; −<span class=\"m-frac\"><span class=\"num\">4</span><span class=\"den\">50</span></span>).<br>Sau 25 giây nữa (tổng 75 giây), ta có: <span class=\"m-vec\">OC</span> = <span class=\"m-vec\">OA</span> + 75·<span class=\"m-vec\">v</span> = (200 + <span class=\"m-frac\"><span class=\"num\">3(x − 200)</span><span class=\"den\">2</span></span>; 70 + <span class=\"m-frac\"><span class=\"num\">3(y − 70)</span><span class=\"den\">2</span></span>; 112).<br>Xét điểm P(80; 105; 113). Giả sử tồn tại t sao cho <span class=\"m-vec\">OP</span> = <span class=\"m-vec\">OA</span> + t·<span class=\"m-vec\">v</span>:<br>80 = 200 + t·<span class=\"m-frac\"><span class=\"num\">x − 200</span><span class=\"den\">50</span></span>; 105 = 70 + t·<span class=\"m-frac\"><span class=\"num\">y − 70</span><span class=\"den\">50</span></span>; 113 = 118 − <span class=\"m-frac\"><span class=\"num\">4t</span><span class=\"den\">50</span></span> ⇒ t = 62,5; x = 104; y = 98 ⇒ Tọa độ B(104; 98; 114).<br>Suy ra <span class=\"m-vec\">v</span> = (−1,92; 0,56; −0,08), C(56; 112; 112).<br>Tính khoảng cách từ sân bay (gốc tọa độ) đến điểm C:<br>d = OC = <span class=\"m-root\">√<span class=\"m-rad\">56² + 112² + 112²</span></span> = <span class=\"m-root\">√<span class=\"m-rad\">28224</span></span> = 168 (đơn vị trục 100 mét/đơn vị).<br>Vậy khoảng cách từ sân bay đến máy bay sau 75 giây là 168·100·<span class=\"m-frac\"><span class=\"num\">1</span><span class=\"den\">1000</span></span> = 16,8 km."
