        "explanation": "Vị trí của máy bay sau 5 phút tiếp theo là P(a; b; c).<br><span class=\"m-vec\">MN</span> = (300; 100; 2); <span class=\"m-vec\">NP</span> = (a − 800; b − 300; c − 10).<br>Do máy bay tiếp tục giữ nguyên vận tốc và hướng bay và thời gian bay từ M đến N gấp bốn lần thời gian bay từ N đến P nên <span class=\"m-vec\">MN</span> = 4<span class=\"m-vec\">NP</span>.<br>⇔ {300 = 4(a − 800); 100 = 4(b − 300); 2 = 4(c − 10)} ⇔ {a = 875; b = 325; c = 10,5}.<br>Từ đó a + b + 2c = 875 + 325 + 2·10,5 = 1221."
