        "explanation": "Gọi x (dm) là bán kính đáy hình trụ (x > 0).<br>Phương án 1: Thể tích lon hình trụ cho bởi công thức V(x) = πx²(2 − 2x) với x ∈ (0; <span class=\"m-frac\"><span class=\"num\">5</span><span class=\"den\">2π</span></span>].<br>Khảo sát hàm số trên (0; <span class=\"m-frac\"><span class=\"num\">5</span><span class=\"den\">2π</span></span>], V(x) đạt giá trị lớn nhất khoảng 0,93 dm³ khi x ≈ 0,67 dm.<br>Phương án 2: Thể tích lon hình trụ cho bởi công thức V(x) = 2πx² với x ∈ (0; <span class=\"m-frac\"><span class=\"num\">5</span><span class=\"den\">2(π + 1)</span></span>].<br>Khảo sát hàm số trên (0; <span class=\"m-frac\"><span class=\"num\">5</span><span class=\"den\">2(π + 1)</span></span>], V(x) đạt giá trị lớn nhất là khoảng 2,29 dm³ khi x ≈ 0,60 dm (tức 6,04 cm).<br>Vậy thể tích lon hình trụ lớn nhất khi thiết kế theo phương án 2 và bán kính đáy khoảng 0,60 dm."
