        "explanation": "Khoảng biến thiên của mẫu số liệu ghép nhóm là 110 − 40 = 70 (thẻ vàng).<br>Với n = 20, ta có <span class=\"m-frac\"><span class=\"num\">n</span><span class=\"den\">4</span></span> = 5 mà 2 < 5 < 7. Suy ra nhóm 2 là nhóm đầu tiên có tần số tích lũy lớn hơn hoặc bằng 5.<br>Xét nhóm 2 là [50; 60) có s = 50, h = 10, n₂ = 5. Nhóm 1 là [40; 50) có cf₁ = 2 ⇒ Q₁ = 50 + <span class=\"m-frac\"><span class=\"num\">5 − 2</span><span class=\"den\">5</span></span>·10 = 56.<br>Ta có: <span class=\"m-frac\"><span class=\"num\">3n</span><span class=\"den\">4</span></span> = 15 mà 14 < 15 < 19 suy ra nhóm 4 là nhóm có tần số tích lũy lớn hơn hoặc bằng 15.<br>Xét nhóm 4 là [70; 80) có t = 70, h = 10, n₄ = 5. Nhóm 3 là [60; 70) có cf₃ = 14 ⇒ Q₃ = 60 + <span class=\"m-frac\"><span class=\"num\">15 − 14</span><span class=\"den\">5</span></span>·10 = 62.<br>Suy ra khoảng tứ phân vị Δ<sub>Q</sub> = Q₃ − Q₁ = 62 − 56 = 6.<br>Giá trị x là giá trị ngoại lệ của mẫu số liệu nếu x < Q₁ − 1,5Δ<sub>Q</sub> hoặc x > Q₃ + 1,5Δ<sub>Q</sub> ⇒ x < 47 hoặc x > 71.<br>Vậy mẫu số liệu trên có hai nhóm chứa giá trị ngoại lệ."
