        "explanation": "Do vận tốc của máy bay không đổi nên thời gian và quãng đường là hai đại lượng tỉ lệ thuận.<br>Thời gian máy bay di chuyển từ M đến Q là 30 phút nên <span class=\"m-frac\"><span class=\"num\">MN</span><span class=\"den\">MQ</span></span> = <span class=\"m-frac\"><span class=\"num\">20</span><span class=\"den\">30</span></span> = <span class=\"m-frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span>, do đó <span class=\"m-vec\">MN</span> = <span class=\"m-frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span><span class=\"m-vec\">MQ</span>.<br>Ta có <span class=\"m-vec\">MN</span> = (x<sub>N</sub> − 1100; y<sub>N</sub> − 650; z<sub>N</sub> − 14); <span class=\"m-vec\">MQ</span> = (400; 210; 2).<br>Suy ra {x<sub>N</sub> = <span class=\"m-frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> · 400 + 1100 = <span class=\"m-frac\"><span class=\"num\">4100</span><span class=\"den\">3</span></span>; y<sub>N</sub> = <span class=\"m-frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> · 210 + 650 = 790; z<sub>N</sub> = <span class=\"m-frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> · 2 + 14 = <span class=\"m-frac\"><span class=\"num\">46</span><span class=\"den\">3</span></span>}, tức là N(<span class=\"m-frac\"><span class=\"num\">4100</span><span class=\"den\">3</span></span>; 790; <span class=\"m-frac\"><span class=\"num\">46</span><span class=\"den\">3</span></span>).<br><span class=\"m-vec\">MN</span> = (<span class=\"m-frac\"><span class=\"num\">800</span><span class=\"den\">3</span></span>; 140; <span class=\"m-frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span>). Ta có <span class=\"m-vec\">ME</span> = (<span class=\"m-frac\"><span class=\"num\">−1600</span><span class=\"den\">3</span></span>; −280; <span class=\"m-frac\"><span class=\"num\">−8</span><span class=\"den\">3</span></span>).<br>Khi đó <span class=\"m-frac\"><span class=\"num\">800/3</span><span class=\"den\">−1600/3</span></span> = <span class=\"m-frac\"><span class=\"num\">140</span><span class=\"den\">−280</span></span> = <span class=\"m-frac\"><span class=\"num\">4/3</span><span class=\"den\">−8/3</span></span> = −<span class=\"m-frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> nên ba điểm M, E, N thẳng hàng; M nằm giữa E và N; ME = 2MN.<br>Giả sử sau x phút khi máy bay bay từ M thì người điều khiển pháo phải bắn.<br>Khi đó vận tốc khẩu pháo là <span class=\"m-frac\"><span class=\"num\">EN</span><span class=\"den\">20 − x</span></span> kilômét/phút; vận tốc máy bay là <span class=\"m-frac\"><span class=\"num\">MN</span><span class=\"den\">20</span></span> kilômét/phút.<br>Theo đề bài <span class=\"m-frac\"><span class=\"num\">EN</span><span class=\"den\">20 − x</span></span> = 5 · <span class=\"m-frac\"><span class=\"num\">MN</span><span class=\"den\">20</span></span> = <span class=\"m-frac\"><span class=\"num\">MN</span><span class=\"den\">4</span></span>.<br>Suy ra <span class=\"m-frac\"><span class=\"num\">3MN</span><span class=\"den\">20 − x</span></span> = <span class=\"m-frac\"><span class=\"num\">MN</span><span class=\"den\">4</span></span> ⇔ 20 − x = 12 ⇔ x = 8.<br>Vậy sau 8 phút khi máy bay bay từ M thì người điều khiển pháo phải bắn."
