          "B": "<span class=\"m-frac\"><span class=\"num\">2<span class=\"m-root\">√<span class=\"m-rad\">21</span></span></span><span class=\"den\">3</span></span>.",
          "C": "<span class=\"m-frac\"><span class=\"num\"><span class=\"m-root\">√<span class=\"m-rad\">39</span></span></span><span class=\"den\">3</span></span>.",
