        "explanation": "Chọn A.<br>Ta có (S): 3x² + 3y² + 3z² − 6x + 12y + 2 = 0 ⇔ x² + y² + z² − 2x + 4y + <span class=\"m-frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> = 0.<br>Tâm mặt cầu là I(1; −2; 0); bán kính của mặt cầu là R = <span class=\"m-root\">√<span class=\"m-rad\">1 + 4 − <span class=\"m-frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span></span></span> = <span class=\"m-root\">√<span class=\"m-rad\"><span class=\"m-frac\"><span class=\"num\">13</span><span class=\"den\">3</span></span></span></span> = <span class=\"m-frac\"><span class=\"num\"><span class=\"m-root\">√<span class=\"m-rad\">39</span></span></span><span class=\"den\">3</span></span>.<br>Suy ra đường kính mặt cầu là: 2R = <span class=\"m-frac\"><span class=\"num\">2<span class=\"m-root\">√<span class=\"m-rad\">39</span></span></span><span class=\"den\">3</span></span>."
